@test
def test_auto():
    cs = mne.compute_covariance(ep, method="auto", return_estimators=True)
    got = [c.method.__val__() for c in cs]
    if got != ['empirical', 'diagonal_fixed', 'shrunk']:
        print("TEST FAILED: auto order", got)
    close("auto_ll", [c.loglik.__val__() for c in cs], [-36.79632882818708, -36.96092998165015, -37.7357615195429], 1e-7)
    close("auto_best", cs[0].data, [3.274973701841472e-24, 5.279392223996605e-25, 1.0902479726541115e-23, 1.0816531613966424e-23, 1.5784641913467955e-17, -1.0844876392550122e-17, 5.279392223996605e-25, 1.0927711841473145e-24, 4.992222125105331e-25, -4.8805268011266685e-25, -1.116756927317306e-18, 3.806563315953126e-18, 1.0902479726541115e-23, 4.992222125105331e-25, 1.622013020497919e-22, -6.515508122043277e-23, 8.525595069678563e-17, -5.076771466203072e-17, 1.0816531613966424e-23, -4.8805268011266685e-25, -6.515508122043277e-23, 2.515491748796315e-22, 4.2513734343756097e-17, -9.20248907330051e-17, 1.5784641913467955e-17, -1.116756927317306e-18, 8.525595069678563e-17, 4.2513734343756097e-17, 2.807438790946804e-10, 5.240810929587161e-12, -1.0844876392550122e-17, 3.806563315953126e-18, -5.076771466203072e-17, -9.20248907330051e-17, 5.240810929587161e-12, 1.5860038533750474e-10])
